code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    candidates = []
    for axis, size in ((0, h), (1, w)):
        lines = {}
        for i in range(size):
            vals = [g[i][j] for j in range(w)] if axis == 0 else [g[j][i] for j in range(h)]
            if vals and all(v == vals[0] for v in vals) and vals[0] != bg:
                lines.setdefault(vals[0], []).append(i)
        for color, indices in lines.items():
            candidates.append((len(indices), axis, color, indices))
    if not candidates:
        return g

    _, axis, sep_color, separators = max(candidates, key=lambda x: x[0])
    size = h if axis == 0 else w
    separators = sorted(separators)
    if len(separators) >= 2:
        gaps = [b-a for a, b in zip(separators, separators[1:])]
        period = max(set(gaps), key=gaps.count)
        if any(gap != period for gap in gaps):
            return g
    else:
        s = separators[0]
        if s == size - s - 1:
            period = s + 1
        else:
            return g

    spans = []
    start = 0
    for sep in separators:
        if sep > start:
            spans.append((start, sep))
        start = sep + 1
    if start < size:
        spans.append((start, size))
    if len(spans) < 2:
        return g

    def get_cell(i, j):
        return g[i][j] if axis == 0 else g[j][i]
    def set_cell(i, j, value):
        if axis == 0:
            g[i][j] = value
        else:
            g[j][i] = value
    def content_count(span):
        a, b = span
        return sum(get_cell(i, j) != bg for i in range(a, b) for j in range(w if axis == 0 else h))

    template_span = max(spans, key=content_count)
    ta, tb = template_span
    template_len = tb - ta
    template = [[get_cell(ta + i, j) for j in range(w if axis == 0 else h)] for i in range(template_len)]
    for a, b in spans:
        if (a, b) == template_span:
            continue
        for i in range(b-a):
            for j in range(w if axis == 0 else h):
                set_cell(a+i, j, template[i % template_len][j])
    return g
'''
